switch (layer.type) {
    case RGB_GIMAGE:
        if (bpp != 3) { bpp = 3; } break;
    case RGBA_GIMAGE:
        if (bpp != 4) { bpp = 4; } break;
    case GRAY_GIMAGE:
        if (bpp != 1) { bpp = 1; } break;
    case GRAYA_GIMAGE:
